function minOperations(nums) {
  let increments = 0;
  let maxBits = 0;

  for (const num of nums) {
    let value = num;
    let bits = 0;
    while (value > 0) {
      increments += value & 1;
      value >>= 1;
      bits++;
    }
    maxBits = Math.max(maxBits, bits);
  }
  const doublings = Math.max(maxBits - 1, 0);
  return increments + doublings;
}

