function minOperations(nums) {
  // Undo the calls from the end: subtract 1 from every odd entry, then halve everything, until all are 0.
  const arr = nums.slice();
  let calls = 0;
  for (;;) {
    for (let i = 0; i < arr.length; i++) {
      if (arr[i] % 2 === 1) { arr[i] -= 1; calls++; }
    }
    if (arr.every(v => v === 0)) return calls;
    for (let i = 0; i < arr.length; i++) arr[i] /= 2;
    calls++;
  }
}

